        Assert.That(result, Is.EqualTo('i').Or.EqualTo('s'));
    }

    private char FindMostFrequentLetter(string word)
    {
        var counts = new Dictionary<char, int>();
        char bestLetter = '\0';
        int bestCount = 0;

        foreach (var ch in word.ToLowerInvariant())
        {
            if (!char.IsLetter(ch))
                continue;

            counts[ch] = counts.GetValueOrDefault(ch) + 1;

            if (counts[ch] > bestCount)
